25: 		protected void warn(string mes, InstructionLine line, int level, bool isBackComp)
26: 		{
27: 			mes = line.Function.Name + "命令:" + mes;
28: 			bool isError = level >= 2;
29: 			if (isError)
30: 			{
31: 				line.IsError = true;
32: 				line.ErrMes = mes;
33: 			}
