36: 		/// <summary>
37: 		/// 引数の型と数。typeof(void)で任意の型（あるいは個別にチェックするべき引数）。nullでその引数は省略可能
38: 		/// </summary>
39: 		protected Type[] argumentTypeArray;//
40: 		/// <summary>
41: 		/// 最低限必要な引数の数。設定しないと全て省略不可。
42: 		/// </summary>
43: 		protected int minArg = -1;
44: 		/// <summary>
45: 		/// 引数の数に制限なし。
46: 		/// </summary>
47: 		protected bool argAny = false;
48: 		protected bool checkArgumentType(InstructionLine line, ExpressionMediator exm, IOperandTerm[] arguments)
49: 		{
50: 			if (arguments == null)
51: 			{
52: 				warn("引数がありません", line, 2, false);
53: 				return false;
54: 			}
55: 			if ( arguments.Length < minArg || 
56: 				((arguments.Length < argumentTypeArray.Length) && (minArg < 0)) )
57: 			{
58: 				warn("引数が足りません", line, 2, false);
59: 				return false;
60: 			}
61: 			int length = arguments.Length;
62: 			if ((arguments.Length > argumentTypeArray.Length)&&(!argAny))
63: 			{
64: 				warn("引数が多すぎます", line, 1, false);
65: 				length = argumentTypeArray.Length;
66: 			}
67: 			for (int i = 0; i < length; i++)
68: 			{
69: 				Type allowType;
70: 				if ((!argAny) && (argumentTypeArray[i] == null))
71: 					continue;
72: 				else if (argAny && i >= argumentTypeArray.Length)
73: 					allowType = argumentTypeArray[argumentTypeArray.Length - 1];
74: 				else
75: 					allowType = argumentTypeArray[i];
76: 				if (arguments[i] == null)
77: 				{
78: 					if (allowType == null)
79: 						continue;
80: 					warn("第" + (i + 1).ToString() + "引数を認識できません", line, 2, false);
81: 					return false;
82: 				}
83: 				if ((allowType != typeof(void)) && (allowType != arguments[i].GetOperandType()))
84: 				{
85: 					warn("第" + (i + 1).ToString() + "引数の型が正しくありません", line, 2, false);
86: 					return false;
87: 				}
88: 			}
89: 			length = arguments.Length;
90: 			for (int i = 0; i < length; i++)
91: 			{
92: 				if (arguments[i] == null)
93: 					continue;
94: 				arguments[i] = arguments[i].Restructure(exm);
95: 			}
96: 			return true;
97: 		}
