130: 	internal static partial class ArgumentParser
131: 	{
132: 		readonly static Dictionary<FunctionArgType, ArgumentBuilder> argb = new Dictionary<FunctionArgType, ArgumentBuilder>();
133: 		
134: 		public static Dictionary<FunctionArgType, ArgumentBuilder> GetArgumentBuilderDictionary()
135: 		{
136: 			return argb;
137: 		}
138: 		public static ArgumentBuilder GetArgumentBuilder(FunctionArgType key)
139: 		{
140: 			return argb[key];
141: 		}
142: 		readonly static Dictionary<string, ArgumentBuilder> nargb = new Dictionary<string, ArgumentBuilder>();
143: 
144: 		/// <summary>
145: 		/// 一般的な引数作成器の呼び出し。数式と文字列式のいずれかのみを引数とし、特殊なチェックが必要ないもの
146: 		/// </summary>
147: 		/// <param name="argstr">大文字のIとSで"IIS"で(int, int, string )のように引数の数と順序を指定する。</param>
148: 		/// <param name="minArg">引数の最低数。これ以降は省略可能</param>
149: 		/// <returns></returns>
150: 		public static ArgumentBuilder GetNormalArgumentBuilder(string argstr, int minArg)
151: 		{
152: 			if (minArg < 0)
153: 				minArg = argstr.Length;
154: 			string key = argstr + minArg.ToString();
155: 			if (nargb.ContainsKey(key))
156: 				return nargb[key];
157: 			Type[] types = new Type[argstr.Length];
158: 			for (int i = 0; i < argstr.Length; i++)
159: 			{
160: 				if (argstr[i] == 'I')
161: 					types[i] = typeof(Int64);
162: 				else if (argstr[i] == 'S')
163: 					types[i] = typeof(string);
164: 				else
165: 					throw new ExeEE("異常な指定");
166: 			}
167: 			ArgumentBuilder newarg = new Expressions_ArgumentBuilder(types, minArg);
168: 			nargb.Add(key, newarg);
169: 			return newarg;
170: 		}
