230: 		private sealed class SP_PRINTV_ArgumentBuilder : ArgumentBuilder
231: 		{
232: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
233: 			{
234: 				StringStream st = line.PopArgumentPrimitive();
235: 				WordCollection wc = LexicalAnalyzer.Analyse(st, LexEndWith.EoL, LexAnalyzeFlag.AnalyzePrintV);
236: 				IOperandTerm[] args = ExpressionParser.ReduceArguments(wc, ArgsEndWith.EoL, false);
237: 				for(int i = 0; i< args.Length;i++)
