SP_TIMES_ArgumentBuilder.text:
248:         private sealed class SP_TIMES_ArgumentBuilder : ArgumentBuilder
249: 		{
250: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
251: 			{
252: 				StringStream st = line.PopArgumentPrimitive();
253: 				WordCollection wc = LexicalAnalyzer.Analyse(st, LexEndWith.Comma, LexAnalyzeFlag.None);
254: 				st.ShiftNext();
255: 				if (st.EOS)
256: 					{warn("引数が足りません", line, 2, false); return null;}
257: 				double d ;
258: 				try
259: 				{
260: 					LexicalAnalyzer.SkipWhiteSpace(st);
261: 					d = LexicalAnalyzer.ReadDouble(st);
262: 					LexicalAnalyzer.SkipWhiteSpace(st);
263: 					if (!st.EOS)
264: 						warn("引数が多すぎます", line, 1, false);
265: 				}
266: 				catch
267: 				{
268: 					warn("第２引数が実数値ではありません（常に0と解釈されます）", line, 1, false);
269: 					d = 0.0;
270: 				}
271: 				IOperandTerm term = ExpressionParser.ReduceExpressionTerm(wc, TermEndWith.EoL);
272: 				if (term == null)
273: 				{ warn("書式が間違っています", line, 2, false); return null; }
274:                 if (!(term.Restructure(exm) is VariableTerm varTerm))
275:                 { warn("第１引数に変数以外を指定することはできません", line, 2, false); return null; }
276:                 else if (varTerm.IsString)
277:                 { warn("第１引数を文字列変数にすることはできません", line, 2, false); return null; }
278:                 else if (varTerm.Identifier.IsConst)
279:                 { warn("第１引数に変更できない変数を指定することはできません", line, 2, false); return null; }
280:                 return new SpTimesArgument(varTerm, d);
281: 			}
282: 		}
