FORM_STR_ANY_ArgumentBuilder.text:
284:         private sealed class FORM_STR_ANY_ArgumentBuilder : ArgumentBuilder
285: 		{
286: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
287: 			{
288: 				Argument ret;
289: 				StringStream st = line.PopArgumentPrimitive();
290: 				List<IOperandTerm> termList = new List<IOperandTerm>();
291: 				LexicalAnalyzer.SkipHalfSpace(st);
292: 				if (st.EOS)
293: 				{
294: 					if (line.FunctionCode == FunctionCode.RETURNFORM)
295: 					{
296: 						termList.Add(new SingleTerm("0"));
297:                         ret = new ExpressionArrayArgument(termList)
298:                         {
299:                             IsConst = true,
300:                             ConstInt = 0
301:                         };
302:                         return ret;
303: 					}
304: 					warn("引数が設定されていません", line, 2, false);
305: 					return null;
306: 				}
307: 				while (true)
308: 				{
309: 					StrFormWord sfwt = LexicalAnalyzer.AnalyseFormattedString(st, FormStrEndWith.Comma, false);
310: 					IOperandTerm term = ExpressionParser.ToStrFormTerm(sfwt);
311: 					term = term.Restructure(exm);
312: 					termList.Add(term);
313: 					st.ShiftNext();
314: 					if (st.EOS)
315: 						break;
316: 					LexicalAnalyzer.SkipHalfSpace(st);
317: 					if (st.EOS)
318: 					{
319: 					    warn("\',\'の後ろに引数がありません。", line, 1, false);
320: 					    break;
321: 					}
322: 				}
323: 				return new ExpressionArrayArgument(termList);
324: 			}
325: 		}
