SP_VAR_ArgumentBuilder.text:
427: 		private sealed class SP_VAR_ArgumentBuilder : ArgumentBuilder
428: 		{
429: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
430: 			{
431: 				StringStream st = line.PopArgumentPrimitive();
432:                 IdentifierWord iw = LexicalAnalyzer.ReadSingleIdentifierWord(st);
433:                 if (iw == null)
434:                 { warn("第１引数を読み取ることができません", line, 2, false); return null; }
435: 				string idStr = iw.Code;
436: 				VariableToken id = GlobalStatic.IdentifierDictionary.GetVariableToken(idStr, null, true);
437: 				if (id == null)
438: 				{ warn("第１引数に変数以外を指定することはできません", line, 2, false); return null; }
439: 				else if ((!id.IsArray1D && !id.IsArray2D && !id.IsArray3D) || (id.Code == VariableCode.RAND))
440: 				{ warn("第１引数に配列でない変数を指定することはできません", line, 2, false); return null; }
441: 				LexicalAnalyzer.SkipWhiteSpace(st);
442: 				if (!st.EOS)
443: 				{
444: 					warn("引数の後に余分な文字があります", line, 1, false);
445: 				}
446: 				return new SpVarsizeArgument(id);
447: 			}
448: 		}
