SP_SORTCHARA_ArgumentBuilder.text:
450: 		private sealed class SP_SORTCHARA_ArgumentBuilder : ArgumentBuilder
451: 		{
452: 			
453: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
454: 			{
455: 				VariableTerm varTerm = new VariableTerm(GlobalStatic.VariableData.GetSystemVariableToken("NO"), new IOperandTerm[] { new SingleTerm(0) });
456: 				SortOrder order = SortOrder.ASCENDING;
457: 				WordCollection wc = popWords(line);
458:                 if (wc.EOL)
459:                 {
460:                     return new SpSortcharaArgument(varTerm, order);
461:                 }
462:                 if ((wc.Current is IdentifierWord id) && (id.Code.Equals("FORWARD", Config.SCVariable)
463: 					|| (id.Code.Equals("BACK", Config.SCVariable))))
464: 				{
465: 					if (id.Code.Equals("BACK", Config.SCVariable))
466: 						order = SortOrder.DESENDING;
467: 					wc.ShiftNext();
468: 					if (!wc.EOL)
469: 						warn("引数が多すぎます", line, 1, false);
470: 				}
471: 				else
472: 				{
473: 					IOperandTerm term = ExpressionParser.ReduceExpressionTerm(wc, TermEndWith.Comma);
474: 					if (term == null)
475: 					{ warn("書式が間違っています", line, 2, false); return null; }
476: 					varTerm = term.Restructure(exm) as VariableTerm;
477: 					if (varTerm == null)
478: 					{ warn("第１引数に変数以外を指定することはできません", line, 2, false); return null; }
479: 					else if (!varTerm.Identifier.IsCharacterData)
480: 					{ warn("第１引数はキャラクタ変数でなければなりません", line, 2, false); return null; }
481: 					wc.ShiftNext();
482: 					if (!wc.EOL)
483: 					{
484: 						id = wc.Current as IdentifierWord;
485: 						if ((id != null) && (id.Code.Equals("FORWARD", Config.SCVariable)
486: 							|| (id.Code.Equals("BACK", Config.SCVariable))))
487: 						{
488: 							if (id.Code.Equals("BACK", Config.SCVariable))
489: 								order = SortOrder.DESENDING;
490: 							wc.ShiftNext();
491: 							if (!wc.EOL)
492: 								warn("引数が多すぎます", line, 1, false);
493: 						}
494: 						else
495: 						{ warn("書式が間違っています", line, 2, false); return null; }
496: 					}
497: 				}
498: 				return new SpSortcharaArgument(varTerm, order);
499: 			}
500: 		}
