551:                         if (!wc.EOL)
552:                         {
553:                             term4 = ExpressionParser.ReduceExpressionTerm(wc, TermEndWith.Comma);
554:                             if (term4 == null)
555:                             { warn("第４引数が解釈出来ません", line, 2, false); return null; }
556:                             if (!term4.IsInteger)
557:                             { warn("第４引数が数値ではありません", line, 2, false); return null; }
558:                             wc.ShiftNext();
559:                             if (!wc.EOL)
560:                                 warn("引数が多すぎます", line, 1, false);
561:                         }
562:                     }
563:                 }
564:                 return new SpArraySortArgument(varTerm, order, term3, term4);
565:             }
566:         }
