SP_CALL_ArgumentBuilder.text:
568: 		private sealed class SP_CALL_ArgumentBuilder : ArgumentBuilder
569: 		{
570: 			public SP_CALL_ArgumentBuilder(bool callf, bool form)
571: 			{
572: 				this.form = form;
573: 				this.callf = callf;
574: 			}
575: 
576:             readonly bool form;
577:             readonly bool callf;
578: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
579: 			{
580: 				StringStream st = line.PopArgumentPrimitive();
581: 				IOperandTerm funcname;
582: 				if (form)
583: 				{
584: 					StrFormWord sfw = LexicalAnalyzer.AnalyseFormattedString(st, FormStrEndWith.LeftParenthesis_Bracket_Comma_Semicolon, true);
585: 					funcname = ExpressionParser.ToStrFormTerm(sfw);
586: 					funcname = funcname.Restructure(exm);
587: 				}
588: 				else
589: 				{
590: 					string str = LexicalAnalyzer.ReadString(st, StrEndWith.LeftParenthesis_Bracket_Comma_Semicolon);
591: 					str = str.Trim(new char[] { ' ', '\t' });
592: 					funcname = new SingleTerm(str);
593: 				}
594: 				char cur = st.Current;
595: 				WordCollection wc = LexicalAnalyzer.Analyse(st, LexEndWith.EoL, LexAnalyzeFlag.None);
596: 				wc.ShiftNext();
597: 
598: 				IOperandTerm[] subNames = null;
599: 				IOperandTerm[] args = null;
600:                 if (cur == '[')
601:                 {
602:                     subNames = ExpressionParser.ReduceArguments(wc, ArgsEndWith.RightBracket, false);
603:                     if (!wc.EOL)
604:                     {
605:                         if (wc.Current.Type != '(')
606:                         wc.ShiftNext();
607:                         args = ExpressionParser.ReduceArguments(wc, ArgsEndWith.RightParenthesis, false);
608:                     }
609:                 }
610: 				if ((cur == '(') || (cur == ','))
611: 				{
612: 					if (cur == '(')
613: 						args = ExpressionParser.ReduceArguments(wc, ArgsEndWith.RightParenthesis, false);
614: 					else
615: 						args = ExpressionParser.ReduceArguments(wc, ArgsEndWith.EoL, false);
616: 					if (!wc.EOL)
617: 					{ warn("書式が間違っています", line, 2, false); return null; }
618: 				}
619: 				if (subNames == null)
620: 					subNames = new IOperandTerm[0];
621: 				if (args == null)
622: 					args = new IOperandTerm[0];
623: 				for(int i = 0; i < subNames.Length; i++)
624: 					if (subNames != null)
625: 						subNames[i] = subNames[i].Restructure(exm);
626: 				for(int i = 0; i < args.Length; i++)
627: 					if (args[i] != null)
628: 						args[i] = args[i].Restructure(exm);
629: 				Argument ret;
630: 				if(callf)
631: 					ret = new SpCallFArgment(funcname, subNames, args);
632: 				else
633: 					ret = new SpCallArgment(funcname, subNames, args);
634:                 if (funcname is SingleTerm)
635:                 {
636:                     ret.IsConst = true;
637:                     ret.ConstStr = funcname.GetStrValue(null);
638:                     if (ret.ConstStr == "")
639:                     {
640:                         warn("関数名が指定されていません", line, 2, false);
641:                         return null;
642:                     }
643:                 }
644: 				return ret;
645: 			}
646: 		}
