SP_SET_ArgumentBuilder.text:
662: 		private sealed class SP_SET_ArgumentBuilder : ArgumentBuilder
663: 		{
664: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm) 
665: 			{
666: 				WordCollection destWc = line.PopAssignmentDestStr();
667: 				IOperandTerm[] destTerms = ExpressionParser.ReduceArguments(destWc, ArgsEndWith.EoL, false);
668: 				SpSetArgument ret;
669: 				if ((destTerms.Length == 0) || (destTerms[0] == null))
670: 				{ assignwarn("代入文の左辺の読み取りに失敗しました", line, 2, false); return null; }
671: 				if (destTerms.Length != 1)
672: 					{assignwarn("代入文の左辺に余分な','があります", line, 2, false); return null;}
673:                 if (!(destTerms[0] is VariableTerm varTerm))
674:                 {//
675:                     assignwarn("代入文の左辺に変数以外を指定することはできません", line, 2, false);
676:                     return null;
677:                 }
678:                 else if (varTerm.Identifier.IsConst)
679:                 {
680:                     assignwarn("代入文の左辺に変更できない変数を指定することはできません", line, 2, false);
681:                     return null;
682:                 }
683:                 varTerm.Restructure(exm);
684: 				StringStream st = line.PopArgumentPrimitive();
685:                 if (st == null)
686:                     st = new StringStream("");
687:                 OperatorCode op = line.AssignOperator;
688: 				IOperandTerm src;
689: 				if(varTerm.IsInteger)
690: 				{
691: 					if (op == OperatorCode.AssignmentStr)
692: 						{ assignwarn("整数型の代入に演算子"+OperatorManager.ToOperatorString(op) + "は使用できません", line, 2, false); return null; }
693: 					if((op == OperatorCode.Increment)||(op == OperatorCode.Decrement))
694: 					{
695: 						LexicalAnalyzer.SkipWhiteSpace(st);
696: 						if (!st.EOS)
697: 						{
698: 							if (op == OperatorCode.Increment)
699: 								{assignwarn("インクリメント行でインクリメント以外の処理が定義されています", line, 2, false);return null;}
700: 							else
701: 								{assignwarn("デクリメント行でデクリメント以外の処理が定義されています", line, 2, false);return null;}
702: 						}
703: 						ret = new SpSetArgument(varTerm, null)
704: 						{
705: 							IsConst = true,
706: 							ConstInt = op == OperatorCode.Increment ? 1 : -1,
707: 							AddConst = true
708:                         };
709: 						return ret;
710: 					}
711: 					WordCollection srcWc = LexicalAnalyzer.Analyse(st, LexEndWith.EoL, LexAnalyzeFlag.None);
712: 					IOperandTerm[] srcTerms = ExpressionParser.ReduceArguments(srcWc, ArgsEndWith.EoL, false);
713: 					
714: 					if ((srcTerms.Length == 0) || (srcTerms[0] == null))
715: 						{assignwarn("代入文の右辺の読み取りに失敗しました", line, 2, false); return null;}
716: 					if (srcTerms.Length != 1)
717: 					{
718: 						if(op != OperatorCode.Assignment)
719: 						{assignwarn("複合代入演算では右辺に複数の値を含めることはできません", line, 2, false); return null;}
720: 						bool allConst = true;
721: 						Int64[] constValues = new Int64[srcTerms.Length];
722: 						for (int i = 0; i < srcTerms.Length; i++)
723: 						{
724: 							if (srcTerms[i] == null)
725: 							{ assignwarn("代入式の右辺の値は省略できません", line, 2, false); return null; }
726: 							if (!srcTerms[i].IsInteger)
727: 							{ assignwarn("数値型変数に文字列は代入できません", line, 2, false); return null; }
728: 							srcTerms[i] = srcTerms[i].Restructure(exm);
729: 							if (allConst && (srcTerms[i] is SingleTerm))
730: 								constValues[i] = srcTerms[i].GetIntValue(null);
731: 							else
732: 								allConst = false;
733: 						}
734:                         SpSetArrayArgument arrayarg = new SpSetArrayArgument(varTerm, srcTerms, constValues)
735:                         {
736:                             IsConst = allConst
737:                         };
738:                         return arrayarg;
739: 					}
740: 					if(!srcTerms[0].IsInteger)
741: 						{assignwarn("数値型変数に文字列は代入できません", line, 2, false); return null;}
742: 					src = srcTerms[0].Restructure(exm);
743: 					if(op == OperatorCode.Assignment)
744: 					{
745: 						ret = new SpSetArgument(varTerm, src);
746: 						if(src is SingleTerm)
747: 						{
748: 							ret.IsConst = true;
749: 							ret.AddConst = false;
750: 							ret.ConstInt = src.GetIntValue(null);
751: 						}
752: 						return ret;
753: 					}
754: 					if((op == OperatorCode.Plus)||(op == OperatorCode.Minus))
755: 					{
756: 						if(src is SingleTerm)
757: 						{
758:                             ret = new SpSetArgument(varTerm, null)
759:                             {
760:                                 IsConst = true,
761: 								ConstInt = op == OperatorCode.Plus ? src.GetIntValue(null) : -src.GetIntValue(null),
762: 								AddConst = true
763:                             };
764: 							return ret;
765: 						}
766: 					}
767: 					src = OperatorMethodManager.ReduceBinaryTerm(op,varTerm, src);
768: 					return new SpSetArgument(varTerm, src);
769: 					
770: 				}
771: 				else
772: 				{
773: 					if (op == OperatorCode.Assignment)
774: 					{
775: 						if (Config.SystemIgnoreStringSet)
776: 						{ assignwarn("文字列代入は禁止されています（'=を用いるかコンフィグオプションを変えてください)", line, 2, false); return null; }
777: 						LexicalAnalyzer.SkipHalfSpace(st);//文字列の代入なら半角スペースだけを読み飛ばす
778: 						//eramakerは代入文では妙なTrim()をする。半端にしか再現できないがとりあえずtrim = true
779: 						StrFormWord sfwt = LexicalAnalyzer.AnalyseFormattedString(st, FormStrEndWith.EoL, true);
780: 						IOperandTerm term = ExpressionParser.ToStrFormTerm(sfwt);
781: 						src = term.Restructure(exm);
782: 						ret = new SpSetArgument(varTerm, src);
783: 						if (src is SingleTerm)
784: 						{
785: 							ret.IsConst = true;
786: 							ret.AddConst = false;
787: 							ret.ConstStr = src.GetStrValue(null);
788: 						}
789: 						return ret;
790: 					}
791: 					else if ((op == OperatorCode.Mult)||(op == OperatorCode.Plus)||(op == OperatorCode.AssignmentStr))
792: 					{
793: 						WordCollection srcWc = LexicalAnalyzer.Analyse(st, LexEndWith.EoL, LexAnalyzeFlag.None);
794: 						IOperandTerm[] srcTerms = ExpressionParser.ReduceArguments(srcWc, ArgsEndWith.EoL, false);
795: 						
796: 						if ((srcTerms.Length == 0) || (srcTerms[0] == null))
797: 							{assignwarn("代入文の右辺の読み取りに失敗しました", line, 2, false); return null;}
798: 						if (op == OperatorCode.AssignmentStr)
799: 						{
800: 							if (srcTerms.Length == 1)
801: 							{
802: 								if (srcTerms[0].IsInteger)
803: 								{ assignwarn("文字列変数に数値型は代入できません", line, 2, false); return null; }
804: 								src = srcTerms[0].Restructure(exm);
805: 								ret = new SpSetArgument(varTerm, src);
806: 								if (src is SingleTerm)
807: 								{
808: 									ret.IsConst = true;
809: 									ret.AddConst = false;
810: 									ret.ConstStr = src.GetStrValue(null);
811: 								}
812: 								return ret;
813: 							}
814: 							bool allConst = true;
815: 							string[] constValues = new string[srcTerms.Length];
816: 							for (int i = 0; i < srcTerms.Length; i++)
817: 							{
818: 								if (srcTerms[i] == null)
819: 								{ assignwarn("代入式の右辺の値は省略できません", line, 2, false); return null; }
820: 								if (srcTerms[i].IsInteger)
821: 								{ assignwarn("文字列変数に数値型は代入できません", line, 2, false); return null; }
822: 								srcTerms[i] = srcTerms[i].Restructure(exm);
823: 								if (allConst && (srcTerms[i] is SingleTerm))
824: 									constValues[i] = srcTerms[i].GetStrValue(null);
825: 								else
826: 									allConst = false;
827: 							}
828:                             SpSetArrayArgument arrayarg = new SpSetArrayArgument(varTerm, srcTerms, constValues)
829:                             {
830:                                 IsConst = allConst
831:                             };
832:                             return arrayarg;
833: 						}
834: 						if (srcTerms.Length != 1)
835: 						{ assignwarn("代入文の右辺に余分な','があります", line, 2, false); return null; }
836: 							
837: 						src = srcTerms[0].Restructure(exm);
838: 						src = OperatorMethodManager.ReduceBinaryTerm(op, varTerm, src);
839: 						return new SpSetArgument(varTerm, src);
840: 					}
841: 					assignwarn("代入式に使用できない演算子が使われました", line, 2, false);
842: 					return null;
843: 				}
844: 			}
845: 		}
