INT_EXPRESSION_ArgumentBuilder.text:
909: 		private sealed class INT_EXPRESSION_ArgumentBuilder : ArgumentBuilder
910: 		{
911: 			public INT_EXPRESSION_ArgumentBuilder(bool nullable)
912: 			{
913: 				argumentTypeArray = new Type[] { typeof(Int64) };
914: 				//if (nullable)妥協
915: 				minArg = 0;
916: 				this.nullable = nullable;
917: 			}
918: 
919:             readonly bool nullable;
920: 
921: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
922: 			{
923: 				IOperandTerm[] terms = popTerms(line);
924: 				if (!checkArgumentType(line, exm, terms))
925: 					return null;
926: 				IOperandTerm term;
927: 				if (terms.Length == 0)
928: 				{
929: 					term = new SingleTerm(0);
930: 					if (!nullable)
931: 					{
932: 						if (line.Function.IsExtended())
933: 							warn("省略できない引数が省略されています。Emueraは0を補います", line, 1, false);
934: 						else
935: 							warn("省略できない引数が省略されています。Emueraは0を補いますがeramakerの動作は不定です", line, 1, false);
936: 					}
937: 				}
938: 				else
939: 				{
940: 					term = terms[0];
941: 				}
942: 				
943: 				if (line.FunctionCode == FunctionCode.REPEAT)
944: 				{
945: 					if ((term is SingleTerm) && (term.GetIntValue(null) <= 0L))
946: 					{
947: 						warn("0回以下のREPEATです。(eramakerではエラーになります)", line, 0, true);
948: 					}
949: 					VariableToken count = GlobalStatic.VariableData.GetSystemVariableToken("COUNT");
950: 					VariableTerm repCount = new VariableTerm(count, new IOperandTerm[] { new SingleTerm(0) });
951: 					repCount.Restructure(exm);
952: 					return new SpForNextArgment(repCount, new SingleTerm(0), term, new SingleTerm(1));
953: 				}
954: 				ExpressionArgument ret = new ExpressionArgument(term);
955: 				if (term is SingleTerm)
956: 				{
957: 					Int64 i = term.GetIntValue(null);
958: 					ret.ConstInt = i;
959: 					ret.IsConst = true;
960: 					if (line.FunctionCode == FunctionCode.CLEARLINE)
961: 					{
962: 						if (i <= 0L)
963: 							warn("引数に0以下の値が渡されています(この行は何もしません)", line, 1, false);
964: 					}
965: 					else if (line.FunctionCode == FunctionCode.FONTSTYLE)
966: 					{
967: 						if (i < 0L)
968: 							warn("引数に負の値が渡されています(結果は不定です)", line, 1, false);
969: 					}
970: 				}
971: 				return ret;
972: 			}
973: 		}
