1323:                 //最初の項はいらない
1324:                 termList.RemoveAt(0);
1325: 				BitArgument ret = new BitArgument(varTerm, termList.ToArray());
1326:                 for (int i = 0; i < termList.Count; i++)
1327:                 {
1328:                     if (termList[i] is SingleTerm term)
1329:                     {
1330:                         Int64 bit = term.Int;
1331:                         if ((bit < 0) || (bit > 63))
