1342: 		private sealed class SP_VAR_SET_ArgumentBuilder : ArgumentBuilder
1343: 		{
1344: 			public SP_VAR_SET_ArgumentBuilder()
1345: 			{
1346: 				argumentTypeArray = new Type[] { typeof(void), typeof(void), typeof(Int64), typeof(Int64) };
1347: 				minArg = 1;
1348: 			}
1349: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
1350: 			{
1351: 				IOperandTerm[] terms = popTerms(line);
1352: 				if (!checkArgumentType(line, exm, terms))
1353: 					return null;
1354: 				VariableTerm varTerm = getChangeableVariable(terms, 1, line);
1355: 				if (varTerm == null)
1356: 					return null;
1357:                 if (varTerm.Identifier.IsConst)
1358:                 {
1359: 					warn("値を変更できない変数" + varTerm.Identifier.Name + "が指定されました", line, 2, false);
1360:                     return null;
1361:                 }
1362: 
1363: 				IOperandTerm term, term3 = null, term4 = null;
1364: 				if (terms.Length > 1)
1365: 					term = terms[1];
1366: 				else
1367: 				{
1368: 					if (varTerm.IsString)
1369: 						term = new SingleTerm("");
1370: 					else
1371: 						term = new SingleTerm(0);
1372: 				}
1373: 				if (varTerm is VariableNoArgTerm)
1374: 				{
1375: 					if (terms.Length > 2)
1376: 					{
1377: 						warn("対象となる変数" + varTerm.Identifier.Name + "の要素を省略する場合には第3引数以降を設定できません", line, 2, false);
1378: 						return null;
1379: 					}
1380: 					return new SpVarSetArgument(new FixedVariableTerm(varTerm.Identifier), term, null, null);
1381: 				}
1382: 				if (terms.Length > 2)
1383: 					term3 = terms[2];
1384: 				if (terms.Length > 3)
1385: 					term4 = terms[3];
1386: 				if (terms.Length >= 3 && !varTerm.Identifier.IsArray1D)
1387: 					warn("第３引数以降は1次元配列以外では無視されます", line, 1, false);
1388: 				if (term.GetOperandType() != varTerm.GetOperandType())
1389: 				{
1390: 					warn("２つの引数の型が一致していません", line, 2, false);
1391: 					return null;
1392: 				}
1393: 				return new SpVarSetArgument(varTerm, term, term3, term4);
1394: 			}
1395: 		}
