1397: 		private sealed class SP_CVAR_SET_ArgumentBuilder : ArgumentBuilder
1398: 		{
1399: 			public SP_CVAR_SET_ArgumentBuilder()
1400: 			{
1401: 				argumentTypeArray = new Type[] { typeof(void), typeof(void), typeof(void), typeof(Int64), typeof(Int64) };
1402: 				minArg = 1;
1403: 			}
1404: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
1405: 			{
1406: 				IOperandTerm[] terms = popTerms(line);
1407: 				if (!checkArgumentType(line, exm, terms))
1408: 					return null;
1409: 
1410: 				VariableTerm varTerm = getChangeableVariable(terms, 1, line);
1411: 				if (varTerm == null)
1412: 					return null;
1413: 				if (!varTerm.Identifier.IsCharacterData)
1414: 				{ warn("第１引数にキャラクタ変数以外の変数を指定することはできません", line, 2, false); return null; }
1415: 				//1803beta004 暫定CDFLAGを弾く
1416: 				if (varTerm.Identifier.IsArray2D)
1417: 				{ warn("第１引数に二次元配列の変数を指定することはできません", line, 2, false); return null; }
1418: 				IOperandTerm index, term, term4 = null, term5 = null;
1419: 				if (terms.Length > 1)
1420: 					index = terms[1];
1421: 				else
1422: 					index = new SingleTerm(0);
1423: 				if (terms.Length > 2)
1424: 					term = terms[2];
1425: 				else
1426: 				{
1427: 					if (varTerm.IsString)
1428: 						term = new SingleTerm("");
1429: 					else
1430: 						term = new SingleTerm(0);
1431: 				}
1432: 				if (terms.Length > 3)
1433: 					term4 = terms[3];
1434: 				if (terms.Length > 4)
1435: 					term5 = terms[4];
1436: 				if (index is SingleTerm term1 && index.GetOperandType() == typeof(string) && varTerm.Identifier.IsArray1D)
1437: 				{
1438: 					if (!GlobalStatic.ConstantData.isDefined(varTerm.Identifier.Code, term1.Str))
1439: 					{ warn("文字列" + index.GetStrValue(null) + "は変数" + varTerm.Identifier.Name + "の要素ではありません", line, 2, false); return null; }
1440: 				}
1441: 				if (terms.Length > 3 && !varTerm.Identifier.IsArray1D)
1442: 					warn("第４引数以降は1次元配列以外では無視されます", line, 1, false);
1443: 				if (term.GetOperandType() != varTerm.GetOperandType())
1444: 				{
1445: 					warn("２つの引数の型が一致していません", line, 2, false);
1446: 					return null;
1447: 				}
1448: 				return new SpCVarSetArgument(varTerm, index, term, term4, term5);
1449: 			}
1450: 		}
