1641: 			public override Argument CreateArgument(InstructionLine line, ExpressionMediator exm)
1642: 			{
1643: 				IOperandTerm[] terms = popTerms(line);
1644: 				if (!checkArgumentType(line, exm, terms))
1645: 					return null;
1646: 				List<VariableToken> varTokens = new List<VariableToken>();
1647: 				for (int i = 2; i < terms.Length; i++)
1648: 				{
1649: 					if (terms[i] == null)
1650: 					{ warn("第" + (i + 1) + "引数を省略できません", line, 2, false); return null; }
1651: 					VariableTerm vTerm = getChangeableVariable(terms, i + 1, line);
1652: 					if (vTerm == null)
1653: 						return null;
1654: 					VariableToken vToken = vTerm.Identifier;
1655: 					if (vToken.IsCharacterData)
1656: 					{ warn("キャラクタ変数"+ vToken.Name+"はセーブできません(キャラクタ変数のSAVEにはSAVECHARAを使用します)", line, 2, false); return null; }
1657: 					if (vToken.IsPrivate)
1658: 					{ warn("プライベート変数" + vToken.Name + "はセーブできません", line, 2, false); return null; }
1659: 					if (vToken.IsLocal)
1660: 					{ warn("ローカル変数" + vToken.Name + "はセーブできません", line, 2, false); return null; }
1661: 					if (vToken.IsConst)
1662: 					{ warn("値を変更できない変数はセーブできません", line, 2, false); return null; }
1663: 					if (vToken.IsCalc)
1664: 					{ warn("疑似変数はセーブできません", line, 2, false); return null; }
1665: 					if (vToken.IsReference)
1666: 					{ warn("参照型変数はセーブできません", line, 2, false); return null; }
1667: 					varTokens.Add(vToken);
1668: 				}
1669: 				for (int i = 0; i < varTokens.Count; i++)
1670: 				{
1671: 					for (int j = i + 1; j < varTokens.Count; j++)
1672: 						if (varTokens[i] == varTokens[j])
1673: 						{
1674: 							warn("変数" + varTokens[i].Name + "を二度以上保存しようとしています", line, 1, false);
1675: 							return null;
1676: 						}
1677: 				}
1678: 				VariableToken[] arg3 = new VariableToken[varTokens.Count];
1679: 				varTokens.CopyTo(arg3);
1680: 				return new SpSaveVarArgument(terms[0], terms[1], arg3);
1681: 			}
1682: 		}
