1738: 			{
1739: 				WordCollection wc = popWords(line);
1740:                 wc.ShiftNext();
1741:                 if (!(wc.Current is IdentifierWord id) || wc.Current.Type != ',')
1742: 				{ warn("書式が間違っています", line, 2, false); return null; }
1743: 				wc.ShiftNext();
1744: 				IOperandTerm name = null;
1745:                 string srcCode = null;
1746: 				if (byname)
1747: 				{
