1749: 					if (name == null || name.IsInteger || !wc.EOL)
1750: 					{ warn("書式が間違っています", line, 2, false); return null; }
1751: 					name = name.Restructure(exm);
1752: 					if (name is SingleTerm)
1753: 						srcCode = name.GetStrValue(exm);
1754: 				}
1755: 				else
1756: 				{
1757:                     wc.ShiftNext();
1758:                     if (!(wc.Current is IdentifierWord id2) || !wc.EOL)
1759: 					{ warn("書式が間違っています", line, 2, false); return null; }
1760: 					srcCode = id2.Code;
1761: 				}
1762: 				UserDefinedRefMethod refm = GlobalStatic.IdentifierDictionary.GetRefMethod(id.Code);
1763: 				ReferenceToken refVar = null;
1764: 				if (refm == null)
1765: 				{
1766: 					VariableToken token = GlobalStatic.IdentifierDictionary.GetVariableToken(id.Code, null, true);
1767: 					if (token == null || !token.IsReference)
1768: 					{ warn("第一引数は関数参照か参照型変数でなければなりません", line, 2, false); return null; }
1769: 					refVar = (ReferenceToken)token;
1770: 				}
1771: 
1772: 				if (refm != null)
1773: 				{
1774: 					if (srcCode == null)
1775: 						return new RefArgument(refm, name);
1776: 					UserDefinedRefMethod srcRef = GlobalStatic.IdentifierDictionary.GetRefMethod(srcCode);
1777: 					if (srcRef != null)
1778: 					{
1779: 						return new RefArgument(refm, srcRef);
1780: 					}
1781: 					FunctionLabelLine label = GlobalStatic.LabelDictionary.GetNonEventLabel(srcCode);
1782: 					if (label == null)
1783: 					{ warn("式中関数" + srcCode + "が見つかりません", line, 2, false); return null; }
1784: 					if (!label.IsMethod)
1785: 					{ warn("#FUNCTION(S)属性を持たない関数" + srcCode + "は参照できません", line, 2, false); return null; }
1786: 					CalledFunction called = CalledFunction.CreateCalledFunctionMethod(label, label.LabelName);
1787: 					return new RefArgument(refm, called);
1788: 				}
1789: 				else
1790: 				{
1791: 					if (srcCode == null)
1792: 						return new RefArgument(refVar, name);
1793: 					VariableToken srcVar = GlobalStatic.IdentifierDictionary.GetVariableToken(srcCode, null, true);
1794: 					if (srcVar == null)
1795: 					{ warn("変数" + srcCode + "が見つかりません", line, 2, false); return null; }
1796: 					return new RefArgument(refVar, srcVar);
1797: 				}
1798: 			}
